using System.Diagnostics; using CodexMultipleAccounts.Core.Launching; using CodexMultipleAccounts.App.ViewModels; using Avalonia.Threading;
namespace CodexMultipleAccounts.App.Terminal;
public sealed class ProcessTerminalLauncher { public TerminalSessionViewModel Launch(string title,CodexLaunchSpec spec){ var vm=new TerminalSessionViewModel(title); var psi=new ProcessStartInfo(spec.Executable){WorkingDirectory=spec.WorkingDirectory,RedirectStandardOutput=true,RedirectStandardError=true,RedirectStandardInput=true,UseShellExecute=false,CreateNoWindow=true}; foreach(var a in spec.Arguments) psi.ArgumentList.Add(a); foreach(var e in spec.Environment) psi.Environment[e.Key]=e.Value; try { var p=Process.Start(psi)??throw new InvalidOperationException("Unable to start Codex."); _=PumpAsync(p,vm); } catch(Exception ex){vm.Output=ex.Message;} return vm; } private static async Task PumpAsync(Process p,TerminalSessionViewModel vm){ var stdout=p.StandardOutput.ReadToEndAsync(); var stderr=p.StandardError.ReadToEndAsync(); await p.WaitForExitAsync(); var text=(await stdout)+(await stderr); await Dispatcher.UIThread.InvokeAsync(()=>vm.Output=string.IsNullOrWhiteSpace(text)?$"Codex exited with code {p.ExitCode}.":text); } }
